def calculate_distance(x, y, z, a, b, c):
    return abs(x + y - a - b) + abs(y + z - b - c) + abs(z + x - c - a)

# Candidate C Questions
Q1 = (9, 0, 0)
Q2 = (0, 9, 0)
Q3 = (0, 0, 9)
Q4 = (9, 9, 9)
Questions = [Q1, Q2, Q3, Q4]

# Dictionary to store the distance vector for each (x, y, z) combination
seen_vectors = {}
total_combinations = 0
collision_found = False

# Iterate over all possible input triples (x, y, z)
for x in range(10):
    for y in range(10):
        for z in range(10):
            total_combinations += 1

            # Calculate the vector of distances
            distances = []
            for i in range(4):
                a, b, c = Questions[i]
                d = calculate_distance(x, y, z, a, b, c)
                distances.append(d)

            vector = tuple(distances)

            # Check for collisions
            if vector in seen_vectors and seen_vectors[vector] != (x, y, z):
                print(f"Collision found: Input ({x}, {y}, {z}) and {seen_vectors[vector]} both yield distance vector {vector}")
                collision_found = True
                break

            seen_vectors[vector] = (x, y, z)
        if collision_found:
            break
    if collision_found:
        break

if not collision_found:
    print("No collisions found for Candidate C over 1000 combinations.")
else:
    print("Collisions were found.")
